public class User
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public HashSet<Guid> Following { get; } = new();
    public List<Post> Posts { get; } = new();
}

public enum PostType { Text, Image, Video }

public class Post
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid AuthorId { get; }
    public PostType Type { get; }
    public string Content { get; set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;
    public int Likes { get; private set; }
    public List<Comment> Comments { get; } = new();
    public double EngagementScore => Likes * 0.5 + Comments.Count * 1.0 + (DateTime.UtcNow - CreatedAt).TotalHours * -0.1;
}

public class FeedService
{
    private readonly Dictionary<Guid, User> _users = new();
    private readonly Dictionary<Guid, List<Post>> _userFeeds = new();

    public IEnumerable<Post> GenerateFeed(Guid userId, int page = 1, int pageSize = 10)
    {
        var user = _users[userId];
        var posts = user.Following
            .SelectMany(fid => _users[fid].Posts)
            .OrderByDescending(p => p.EngagementScore)
            .ThenByDescending(p => p.CreatedAt);
        return posts.Skip((page - 1) * pageSize).Take(pageSize);
    }
}
